import{_ as d,C as i,o as h,c as m,j as e,a as r,E as l,a3 as n}from"./chunks/framework.D4-ViStF.js";const f=JSON.parse('{"title":"系辞下传","description":"《易传》之总纲下篇——从卦爻之变、观象制器，到忧患意识与察言观势，讲《易》如何从天地之理落到现实中的行动。","frontmatter":{"title":"系辞下传","description":"《易传》之总纲下篇——从卦爻之变、观象制器，到忧患意识与察言观势，讲《易》如何从天地之理落到现实中的行动。","category":"guide","aliases":["系辞下传","系辞下","xi ci zhuan xia"],"source":["《周易·系辞下传》"]},"headers":[],"relativePath":"yijing/shi-yi/xi-ci-zhuan-xia.md","filePath":"yijing/shi-yi/xi-ci-zhuan-xia.md","lastUpdated":1788140575000}'),p={name:"yijing/shi-yi/xi-ci-zhuan-xia.md"};function u(c,a,y,g,b,x){const t=i("DaoReadingPrelude"),o=i("DaoTextReading"),s=i("DaoKeywordCards");return h(),m("div",null,[a[0]||(a[0]=e("h1",{id:"系辞下传",tabindex:"-1"},[r("系辞下传 "),e("a",{class:"header-anchor",href:"#系辞下传","aria-label":'Permalink to "系辞下传"'},"​")],-1)),l(t,{title:"先读变化如何落入日用",summary:"《系辞下传》承接上传，却把视线从易道之体进一步推向易道之用：卦爻如何呈现变化，圣人如何观象制器，君子如何藏器待时、见几而作，又如何在关系、位置与忧患中守住无咎。全篇九章，像一条从象到器、从器到事、从事到德的路。",points:[{label:"先看象",text:"八卦、重卦、刚柔与爻位，先构成一套观察变化的语言。"},{label:"再看用",text:"观象制器、穷则变通，说明《易》如何进入生计、制度与行动。"},{label:"最后看人",text:"忧患、见几、安身、守位，最终都要求人在变化中承担自己的位置。"}],hint:"下传的心得不宜只当成金句收藏。可以边读原典，边问：这一段看见了什么变化？它要求什么准备？我现在处在怎样的时位？"}),a[1]||(a[1]=n("",12)),l(o,{colophon:"观象制器 · 穷变通久 · 作易忧患 · 惧以终始",tone:"ink",sections:[{id:"duan-01",sentences:[["八卦成列，象在其中矣；"],["因而重之，爻在其中矣；"],["刚柔相推，变在其中焉；"],["系辞焉而命之，动在其中矣。"],["吉凶悔吝者，生乎动者也；"],["刚柔者，立本者也；变通者，趣时者也。"],["吉凶者，贞胜者也；天地之道，贞观者也；"],["日月之道，贞明者也；天下之动，贞夫一者也。"],["夫乾，确然示人易矣；夫坤，隤然示人简矣。"],["爻也者，效此者也；象也者，像此者也；"],["爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。"],["天地之大德曰生，圣人之大宝曰位。何以守位？曰仁。何以聚人？曰财。理财正辞、禁民为非曰义。"]]},{id:"duan-02",sentences:[["古者包牺氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文，与地之宜，近取诸身，远取诸物；"],["于是始作八卦，以通神明之德，以类万物之情。"],["作结绳而为网罟，以佃以渔，盖取诸《离》。"],["包牺氏没，神农氏作，斲木为耜，揉木为耒，耒耨之利，以教天下，盖取诸《益》。"],["日中为市，致天下之民，聚天下之货，交易而退，各得其所，盖取诸《噬嗑》。"],["神农氏没，黄帝、尧、舜氏作，通其变，使民不倦；神而化之，使民宜之。"],["《易》穷则变，变则通，通则久；是以自天祐之，吉无不利。"],["黄帝、尧、舜垂衣裳而天下治，盖取诸《乾》《坤》。"],["刳木为舟，剡木为楫，舟楫之利，以济不通，致远以利天下，盖取诸《涣》。"],["服牛乘马，引重致远，以利天下，盖取诸《随》。重门击柝，以待暴客，盖取诸《豫》。"],["断木为杵，掘地为臼，杵臼之利，万民以济，盖取诸《小过》。"],["弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸《睽》。"],["上古穴居而野处，后世圣人易之以宫室，上栋下宇，以待风雨，盖取诸《大壮》。"],["古之葬者，厚衣之以薪，葬之中野，不封不树，丧期无数；后世圣人易之以棺椁，盖取诸《大过》。"],["上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸《夬》。"]]},{id:"duan-03",sentences:[["是故《易》者，象也；象也者，像也；彖者，材也；爻也者，效天下之动者也。"],["是故吉凶生而悔吝著也。"],["阳卦多阴，阴卦多阳，其故何也？阳卦奇，阴卦偶。"],["其德行何也？阳一君而二民，君子之道也；阴二君而一民，小人之道也。"]]},{id:"duan-04",sentences:[["《易》曰：“憧憧往来，朋从尔思。”子曰：“天下何思何虑！天下同归而殊途，一致而百虑，天下何思何虑！"],["日往则月来，月往则日来，日月相推而明生焉；寒往则暑来，暑往则寒来，寒暑相推而岁成焉。"],["往者，屈也；来者，信也。屈信相感而利生焉。尺蠖之屈，以求信也；龙蛇之蛰，以存身也。"],["精义入神，以致用也；利用安身，以崇德也。过此以往，未之或知也；穷神知化，德之盛也。”"],["《易》曰：“困于石，据于蒺藜，入于其宫，不见其妻，凶。”"],["子曰：“非所困而困焉，名必辱；非所据而据焉，身必危；既辱且危，死期将至，妻其可得见邪？”"],["《易》曰：“公用射隼于高墉之上，获之，无不利。”"],["子曰：“隼者，禽也；弓矢者，器也；射之者，人也。君子藏器于身，待时而动，何不利之有。动而不括，是以出而有获，语成器而动者也。”"],["子曰：“小人不耻不仁，不畏不义，不见利不劝，不威不惩。小惩而大诫，此小人之福也。善不积不足以成名，恶不积不足以灭身。”"],["子曰：“危者，安其位者也；亡者，保其存者也；乱者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘乱。”"],["子曰：“德薄而位尊，知小而谋大，力小而任重，鲜不及矣。”"],["子曰：“知几其神乎！君子见几而作，不俟终日。”"],["子曰：“颜氏之子，其殆庶几乎！有不善，未尝不知；知之，未尝复行也。天地絪缊，万物化醇；男女构精，万物化生。三人行，则损一人；一人行，则得其友。言致一也。”"],["子曰：“君子安其身而后动，易其心而后语，定其交而后求。君子脩此三者，故全也。”"]]},{id:"duan-05",sentences:[["子曰：“乾坤，其《易》之门邪！乾，阳物也；坤，阴物也。阴阳合德，而刚柔有体，以体天地之撰，以通神明之德。”"],["其称名也，杂而不越，于稽其类，其衰世之意邪！"],["夫《易》，彰往而察来，而微显阐幽，开而当名辨物，正言断辞，则备矣。"],["其称名也小，其取类也大；其旨远，其辞文；其言曲而中，其事肆而隐；因贰以济民行，以明失得之报。"]]},{id:"duan-06",sentences:[["《易》之兴也，其于中古乎？作《易》者，其有忧患乎？是故：履，德之基也；谦，德之柄也；复，德之本也；恒，德之固也；损，德之脩也；益，德之裕也；困，德之辨也；井，德之地也；巽，德之制也。"],["履，和而至；谦，尊而光；复，小而辨于物；恒，杂而不厌；损，先难而后易；益，长裕而不没；困，穷而通；井，居其所而迁；巽，称而隐。"],["履，以和行；谦，以制礼；复，以自知；恒，以一德；损，以远害；益，以兴利；困，以寡怨；井，以辨义；巽，以行权。"]]},{id:"duan-07",sentences:[["《易》之为书也不可远，为道也屡迁；变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适。"],["其出入以度，外内使知惧；又明于忧患与故，无有师保，如临父母。"],["初率其辞而揆其方，既有典常；苟非其人，道不虚行。"],["《易》之为书也，原始要终以为质也。六爻相杂，唯其时物也。其初难知，其上易知，本末也。"],["初辞拟之，卒成之终。若夫杂物撰德，辨是与非，则非其中爻不备。噫，亦要存亡吉凶，则居可知矣；知者观其彖辞，则思过半矣。"]]},{id:"duan-08",sentences:[["二与四同功而异位，其善不同：二多誉，四多惧，近也。柔之为道，不利近者，其要无咎，其用柔中也。"],["三与五同功而异位，其遇不同：三多凶，五多功，贵贱之等也。其柔危，其刚胜邪？"],["《易》之为书也，广大悉备：有天道焉，有人道焉，有地道焉，兼三才而两之，故六。"],["六者，非它也，三才之道也。道有变动，故曰爻；爻有等，故曰物；物相杂，故曰文；文不当，故吉凶生焉。"],["《易》之兴也，其当殷之末世，周之盛德邪？当文王与纣之事邪？是故其辞危，危者使平，易者使倾，其道甚大，百物不废，惧以终始，其要无咎；此之谓《易》之道也。"]]},{id:"duan-09",sentences:[["夫乾，天下之至健也；德行恒易以知险。夫坤，天下之至顺也；德行恒简以知阻。"],["能说诸心，能研诸侯之虑，定天下之吉凶，成天下之亹亹者。"],["是故变化云为，吉事有祥；象事知器，占事知来。"],["天地设位，圣人成能；人谋鬼谋，百姓与能。"],["八卦以象告，爻彖以情言，刚柔杂居，而吉凶可见矣。变动以利言，吉凶以情迁。"],["是故爱恶相攻而吉凶生，远近相取而悔吝生，情伪相感而利害生。"],["凡《易》之情，近而不相得则凶，或害之，悔且吝。"],["将叛者其辞惭，中心疑者其辞枝；吉人之辞寡，躁人之辞多；诬善之人其辞游，失其守者其辞屈。"]]}],"aria-label":"系辞下传原文"}),a[2]||(a[2]=e("blockquote",null,[e("p",null,"注：本页原典采用通行本分章。不同版本在「无／无有」「修／脩」「简／簡」等字形、句读和个别字词上可能有异文，阅读时以所据底本为准。")],-1)),a[3]||(a[3]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),l(s,{items:[{term:"趣时",pinyin:["qū","shí"],meaning:"趋向、合于时势。「变通者，趣时者也」不是随波逐流，而是守住根本后，采取与时位相合的做法。"},{term:"位",pinyin:["wèi"],meaning:"爻所处的位置，也指人在天地人事中的职责位置。「圣人之大宝曰位」强调位置意味着承担，而不只是拥有。"},{term:"贞",pinyin:["zhēn"],meaning:"正、定、守住根本。「吉凶者，贞胜者也」说的是变化之中仍有可守的正与一，并非只指占问。"},{term:"制器",pinyin:["zhì","qì"],meaning:"从象所呈现的结构与功能中制作器物、制度和方法。「观象制器」让形上之理落到生活的实际需要。"},{term:"穷",pinyin:["qióng"],meaning:"走到尽头、受阻、原有方式难以继续，并不只指贫穷。「穷则变」首先要求看见旧路已经不通。"},{term:"变通",pinyin:["biàn","tōng"],meaning:"在变化中调整做法，使事理重新流行。「变」不是乱变，「通」也不是只求方便，而是因时而变、通达而久。"},{term:"几",pinyin:["jī"],meaning:"事情将动未动的细微征兆，也是吉凶最先显露的地方。「见几而作」要求在苗头阶段辨认并行动。"},{term:"藏器",pinyin:["cáng","qì"],meaning:"把能力、准备与可用之才蓄积在身。「待时」不是拖延，而是先使自己成为能够承担行动的人。"},{term:"三陈九卦",pinyin:["sān","chén","jiǔ","guà"],meaning:"履、谦、复、恒、损、益、困、井、巽九卦的三层排列，分别说明德性根基、具体表现与行动方法。"},{term:"忧患",pinyin:["yōu","huàn"],meaning:"对失位、失时、失守及其后果的清醒觉察。「作《易》者，其有忧患乎」不是制造焦虑，而是让人预见并修正。"},{term:"无咎",pinyin:["wú","jiù"],meaning:"不陷入无法挽回的过失，也包含知错能改、及时止损。「其要无咎」是《易》对行动者的基本要求。"},{term:"亹亹",pinyin:["wěi","wěi"],meaning:"勤勉不倦、不断前进的样子。「成天下之亹亹」指让天下的事业持续生长，而不是一时的兴奋。"},{term:"说诸心",pinyin:["tuō","zhū","xīn"],meaning:"「说」通「悦」，使人心悦诚服，也使疑虑得到安顿；不是迎合，而是让事理真正进入人心。"},{term:"情伪",pinyin:["qíng","wěi"],meaning:"真实与虚伪，也泛指事情的实际情状与人为伪饰。「情伪相感」说明关系中的真伪会造成不同的利害走向。"}]}),a[4]||(a[4]=n("",48))])}const P=d(p,[["render",u]]);export{f as __pageData,P as default};
